func (d *DefaultNode) EndpointsWithParked() []clablinks.Endpoint {
	if d.parkingNode == nil {
		return d.Endpoints
	}
	return append(slices.Clone(d.Endpoints), d.parkingNode.GetEndpoints()...)
}

