		n.Pid,
		n.mgmtSlot,
		n.mgmtPort,
		n.mgmtSlot,
		n.mgmtPort,
	)

	slot, port := 0, 0

	// Regexp to pull number out of linux'ethX' interface naming
	IntfRegExpr := regexp.MustCompile(`\d+`)

